// A heading in the fantasy font: one SVG, `height` px tall, as wide as the
// words need. `shadow` draws a 1px dark offset under the letters.
export function fantasyTextSvg(text: string, color: string, height = 18, shadow?: string): { svg: string; width: number; height: number } {
  let x = 0
  const parts: string[] = []
  for (const ch of text) {
    const glyph = GLYPHS[ch] ?? GLYPHS[ch.toUpperCase()] ?? GLYPHS[' ']
    if (glyph === undefined) continue
    if (glyph[1] !== '') parts.push(`<path transform="translate(${x} 0)" d="${glyph[1]}"/>`)
    x += glyph[0]
  }
  const scale = height / HEIGHT
  const width = Math.max(1, Math.ceil(x * scale) + 2)
  const letters = parts.join('')
  const under = shadow === undefined ? '' : `<g fill="${shadow}" transform="translate(${(1 / scale).toFixed(1)} ${(1 / scale).toFixed(1)})">${letters}</g>`
  return {
    svg: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${Math.ceil(x) + Math.ceil(2 / scale)} ${HEIGHT}" width="${width}" height="${height}">${under}<g fill="${color}">${letters}</g></svg>`,
    width,
    height,
  }
}

export const FANTASY_EM = EM
